    wire logic [0:0] n0_6 = r0_6[4] ? 1'd0 : ((r0_6 > 5'sd1) ? {1{1'b1}} : r0_6[0:0]);
    wire logic signed [1:0] l0n7_w1 = 2'($signed({1'b0, t0_0}));
    wire logic signed [1:0] l0n7_w2 = 2'($signed({1'b0, t0_1}));
    wire logic signed [1:0] l0n7_w3 = 2'($signed({1'b0, t0_2}));
