        qn0_1 <= n0_1;
        qn0_2 <= n0_2;
        qn0_3 <= n0_3;
        qn0_4 <= n0_4;
        qn0_5 <= n0_5;
        qn0_6 <= n0_6;
        qn0_7 <= n0_7;
    end
    // layer 2: 3 neurons x 8 inputs, class scores (signed)
    wire logic signed [1:0] l1n0_w1 = 2'($signed({1'b0, qn0_0}));
    wire logic signed [1:0] l1n0_w2 = 2'($signed({1'b0, qn0_1}));
    wire logic signed [1:0] l1n0_w3 = 2'($signed({1'b0, qn0_2}));
    wire logic signed [1:0] l1n0_w4 = 2'($signed({1'b0, qn0_3}));
    wire logic signed [1:0] l1n0_w5 = 2'($signed({1'b0, qn0_4}));
    wire logic signed [1:0] l1n0_w6 = 2'($signed({1'b0, qn0_5}));
    wire logic signed [1:0] l1n0_w7 = 2'($signed({1'b0, qn0_6}));
