    wire logic signed [1:0] l1n2_w2 = 2'($signed({1'b0, qn0_1}));
    wire logic signed [1:0] l1n2_w3 = 2'($signed({1'b0, qn0_2}));
    wire logic signed [1:0] l1n2_w4 = 2'($signed({1'b0, qn0_3}));
    wire logic signed [1:0] l1n2_w5 = 2'($signed({1'b0, qn0_4}));
