    wire logic signed [1:0] l1n2_w9 = 2'sd1;
    wire logic signed [1:0] l1n2_w10 = 2'(l1n2_w2) - 2'(l1n2_w1);
    wire logic signed [2:0] l1n2_w11 = 3'(l1n2_w3) + 3'(l1n2_w4);
    wire logic signed [1:0] l1n2_w12 = 2'(l1n2_w6) - 2'(l1n2_w5);
    wire logic signed [1:0] l1n2_w13 = 2'(l1n2_w7) - 2'(l1n2_w8);
    wire logic signed [2:0] l1n2_w14 = 3'(l1n2_w10) - 3'(l1n2_w11);
    wire logic signed [2:0] l1n2_w15 = 3'(l1n2_w12) + 3'(l1n2_w13);
    wire logic signed [3:0] l1n2_w16 = 4'(l1n2_w14) + 4'(l1n2_w15);
